parameters.jsCode:
const ctx = $('Prepare 62 Intent Classifier Context').first().json || {};
const catalog = Array.isArray(ctx.intent_catalog) ? ctx.intent_catalog : [];
const byName = new Map(catalog.map(r=>[String(r.spm_intent||'').trim(),r]));
const clean=v=>String(v??'').trim();
function parse(v){
 if(v && typeof v==='object' && !Array.isArray(v)) return v;
 let t=clean(v).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
 try{return JSON.parse(t)}catch{}
 const a=t.indexOf('{'),b=t.lastIndexOf('}');
 if(a>=0&&b>a){try{return JSON.parse(t.slice(a,b+1))}catch{}}
 return {};
}
const raw=parse($json.output ?? $json.text ?? $json.response ?? $json);
let primary=clean(raw.spm_intent || raw.primary_intent);
let secondary=clean(raw.secondary_spm_intent || raw.secondary_intent);
let confidence=Number(raw.confidence);
if(!Number.isFinite(confidence)||confidence<0||confidence>1) confidence=0;
const ambiguous=raw.ambiguous===true || clean(raw.ambiguous).toLowerCase()==='true';
const language=['ar','en','fr'].includes(clean(raw.language).toLowerCase()) ? clean(raw.language).toLowerCase() : (ctx.language_hint||'');
const matched=byName.get(primary);
const validIntent=Boolean(matched);
if(!validIntent){ primary='out_of_scope'; }
const authoritative=byName.get(primary) || {spm_intent:'out_of_scope',required_entities:[],source_gate:'APPROVED_KB_OR_LOGIC',risk_tier:'A',sales_stage:'none',min_confidence:0.85};
if(!byName.has(secondary) || secondary===primary) secondary='';
const threshold=Number.isFinite(Number(authoritative.min_confidence)) ? Number(authoritative.min_confidence) : 0.85;
let route='direct';
if(!validIntent || confidence<0.60) route='fallback';
else if(ambiguous || confidence<threshold) route='clarify';
const direct=route==='direct';
const result={
 schema:'SPM_CLASSIFIER_OUTPUT_V2',
 spm_intent:primary,
 secondary_spm_intent:secondary,
 confidence,
 threshold,
 ambiguous: ambiguous || !validIntent,
 required_entities:Array.isArray(authoritative.required_entities)?authoritative.required_entities:[],
 source_gate:clean(authoritative.source_gate),
 risk_tier:clean(authoritative.risk_tier),
 sales_stage:clean(authoritative.sales_stage),
 language,
 rationale_code:clean(raw.rationale_code) || (validIntent?'MODEL_CLASSIFICATION':'INVALID_MODEL_INTENT_RECOVERED'),
 intent_valid:validIntent,
 classifier_gate_passed:direct
};
const state={...(ctx.sales_state||{})};
state.classifier={...(state.classifier||{}),...result};
return [{json:{...ctx,sales_state:state,classification:result,classifier_route:route,classifier_gate_passed:direct,customer_clarification_required:route!=='direct',irreversible_action_allowed:false,classifier_validation_errors:validIntent?[]:['MODEL_INTENT_NOT_IN_ACTIVE_CATALOG']}}];

const j=$input.first().json||{};
const requested=String(j.sales_agent_output?.proposed_action||'none');
const irreversible=['lead_upsert','booking_create','booking_change','payment_action','human_handoff_create','contact_update','opt_out_write'];
const stateSaveFailed=j.wu95_state_persisted_test_namespace===false || Boolean(j.wu95_state_save_error);
let reason=stateSaveFailed?'WU97_STATE_PERSISTENCE_FAILED_FAIL_CLOSED':'WU97_IRREVERSIBLE_WRITE_ADAPTERS_NOT_CERTIFIED';
const result={requested_action:requested,executed:false,status:'NOOP_WU97',business_reference:null,reason_code:reason,irreversible_action:irreversible.includes(requested),fail_closed:Boolean(stateSaveFailed||j.wu97_runtime_health?.fail_closed)};
return [{json:{...j,action_gateway_contract:{schema:'SPM_ACTION_GATEWAY_V2',rule:'all irreversible actions require deterministic validation, healthy dependencies, idempotency where applicable, and explicit tool success before success may be reported',allowed_in_wu97:['none','ask_clarification','request_live_check','respect_opt_out'],production_writes_enabled:false},action_result:result}}];

const j=$input.first().json||{};
const duration=Math.max(0,Date.now()-Number(j.started_ms||Date.now()));
const codes=[...(j.wu97_runtime_health?.error_codes||[]),...(j.wu97_runtime_health?.warning_codes||[])];
if(j.wu95_state_persisted_test_namespace===false && !codes.includes('STATE_SAVE_FAILED'))codes.push('STATE_SAVE_FAILED');
const degraded=Boolean(j.wu97_runtime_health?.degraded || j.wu95_state_persisted_test_namespace===false);
const telemetry={schema_version:'SPM_TELEMETRY_V2',timestamp:new Date().toISOString(),correlation_id:j.correlation_id||null,workflow_release:'WU97_RELIABILITY_PRIVACY_SECURITY',test_mode:Boolean(j.test_mode),intent:j.classification?.spm_intent||null,confidence:j.classification?.confidence??null,journey_stage:j.journey_decision?.stage||null,source_gate:j.source_gate_result?.gate||j.source_gate_decision?.gate||null,proposed_action:j.sales_agent_output?.proposed_action||null,action_status:j.action_result?.status||null,action_executed:Boolean(j.action_result?.executed),duration_ms:duration,degraded,recovery_mode:j.action_result?.fail_closed?'SAFE_FAIL_CLOSED':(j.wu97_runtime_health?.recovery_mode||'NORMAL'),error_codes:[...new Set(codes)].slice(0,20),pii_redacted:true,raw_session_logged:false,raw_message_logged:false,secret_values_logged:false};
return [{json:{...j,telemetry}}];

const base=$('Capture WU89 Classifier Context').first().json || {};
const rows=$input.all().map(i=>i.json||{});
const active=rows.filter(r=>String(r.status??'').trim().toUpperCase()==='ACTIVE').map(r=>({
 entity_name:String(r.entity_name??'').trim(),
 data_type:String(r.data_type??'').trim(),
 sensitivity:String(r.sensitivity??'').trim(),
 source_of_truth:String(r.source_of_truth??'').trim(),
 validation_rule:String(r.validation_rule??'').trim(),
 usage:String(r.usage??'').trim()
})).filter(r=>r.entity_name);
const unique=new Set(active.map(r=>r.entity_name));
const ready=active.length===47 && unique.size===47;
return [{json:{...base,entity_contract:{
 schema:'SPM_ENTITY_OUTPUT_V2',
 expected_schema_rows:47,
 raw_preservation:true,
 output_record:['entity','raw','canonical','confidence','source','status','sensitivity','is_correction'],
 multi_student:'students[] are separate profiles and must never be collapsed',
 correction_precedence:'latest explicit customer correction wins unless live/system source owns final truth',
 timezone_rule:'never infer timezone from country alone',
 pii_rule:'exclude PII values from telemetry and aggressive correction'
},entity_schema:active,entity_schema_ready:ready,entity_schema_count:active.length}}];

const base=$('Build WU89 Entity Schema Context').first().json || {};
const rules=$input.all().map(i=>i.json||{}).filter(r=>String(r.status??'').trim().toUpperCase()==='ACTIVE').map(r=>({
 rule_id:String(r.rule_id??'').trim(),language:String(r.language??'').trim(),area:String(r.area??'').trim(),
 raw_pattern_or_example:String(r.raw_pattern_or_example??'').trim(),normalized_or_action:String(r.normalized_or_action??'').trim(),
 safety_rule:String(r.safety_rule??'').trim()
})).filter(r=>r.rule_id);
const ready=rules.length===29 && new Set(rules.map(r=>r.rule_id)).size===29;
const schema=(base.entity_schema||[]).map(r=>({entity:r.entity_name,type:r.data_type,sensitivity:r.sensitivity,validation:r.validation_rule}));
return [{json:{...base,normalization_rules:rules,normalization_ready:ready,normalization_count:rules.length,
 entity_schema_text:JSON.stringify(schema),
 normalization_rules_text:JSON.stringify(rules)}}];

